-- RRTrack 2.0 - INSTALACAO DO BANCO (versao compacta)
-- O SQL Editor do Supabase corta o script na linha 100; esta versao cabe.
-- Mesmo conteudo de INSTALAR.sql, sem as quebras de linha. Cole tudo e rode.

do $inst0$ begin if not exists (select 1 from pg_namespace where nspname = 'vault') then raise exception using errcode = 'undefined_schema', message = 'O Supabase Vault não está ativo neste projeto', hint = 'Vá em Database > Extensions, ative "supabase_vault" e rode este arquivo de novo.'; end if; raise notice 'Cofre (Supabase Vault) disponivel.'; end; $inst0$; create extension if not exists pgcrypto with schema extensions; do $b001$ begin if not exists (select 1 from pg_namespace where nspname = 'vault') then raise exception using errcode = 'undefined_schema', message = 'O schema "vault" não existe neste projeto', hint = 'Ative a extensão "supabase_vault" em Database > Extensions e rode de novo.'; end if; end; $b001$; create schema if not exists private; revoke all on schema private from public, anon, authenticated; grant usage on schema private to service_role; create or replace function private.guardar_segredo( p_id_atual uuid, p_nome text, p_segredo text ) returns uuid language plpgsql volatile security definer set search_path = '' as $b002$ declare v_id uuid; begin if p_segredo is null or length(trim(p_segredo)) = 0 then raise exception 'segredo vazio'; end if; if p_id_atual is null then select vault.create_secret( p_segredo, p_nome || '_' || replace(gen_random_uuid()::text, '-', ''), 'RRTrack' ) into v_id; return v_id; end if; perform vault.update_secret(p_id_atual, p_segredo); return p_id_atual; end; $b002$; create or replace function private.ler_segredo(p_id uuid) returns text language plpgsql stable security definer set search_path = '' as $b003$ declare v_segredo text; begin if p_id is null then return null; end if; select decrypted_secret into v_segredo from vault.decrypted_secrets where id = p_id; return v_segredo; end; $b003$;
create or replace function private.esquecer_segredo(p_id uuid) returns void language plpgsql volatile security definer set search_path = '' as $b004$ begin if p_id is not null then delete from vault.secrets where id = p_id; end if; end; $b004$; create or replace function private.secret_last4(p_secret text) returns text language sql immutable set search_path = '' as $b005$ select case when p_secret is null or length(p_secret) < 4 then null else right(p_secret, 4) end; $b005$; revoke all on function private.guardar_segredo(uuid, text, text) from public, anon, authenticated; revoke all on function private.ler_segredo(uuid) from public, anon, authenticated; revoke all on function private.esquecer_segredo(uuid) from public, anon, authenticated; revoke all on function private.secret_last4(text) from public, anon, authenticated; create or replace function private.touch_updated_at() returns trigger language plpgsql set search_path = '' as $b006$ begin new.updated_at := now(); return new; end; $b006$; create table if not exists public.settings ( id boolean primary key default true, webhook_token_secret_id uuid, webhook_token_last4 text, currency text not null default 'BRL', test_event_code text, allowed_origins text[] not null default '{}', cookie_domain text, insights_cache_ttl_minutes integer not null default 360, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint settings_linha_unica check (id), constraint settings_currency_iso check (currency ~ '^[A-Z]{3}$'), constraint settings_ttl_sensato check (insights_cache_ttl_minutes between 5 and 10080) ); insert into public.settings (id) values (true) on conflict (id) do nothing;
create table if not exists public.ga4_accounts ( id uuid primary key default gen_random_uuid(), label text not null, measurement_id text not null unique, api_secret_secret_id uuid, secret_last4 text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint ga4_measurement_id_formato check (measurement_id ~ '^G-[A-Z0-9]+$') ); create table if not exists public.meta_pixels ( id uuid primary key default gen_random_uuid(), label text not null, pixel_id text not null unique, capi_token_secret_id uuid, secret_last4 text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint meta_pixel_id_numerico check (pixel_id ~ '^[0-9]{5,}$') ); create table if not exists public.meta_ad_accounts ( id uuid primary key default gen_random_uuid(), label text not null, ad_account_id text not null unique, ads_token_secret_id uuid, secret_last4 text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint meta_ad_account_numerico check (ad_account_id ~ '^[0-9]{5,}$') ); drop trigger if exists settings_touch on public.settings; create trigger settings_touch before update on public.settings for each row execute function private.touch_updated_at(); drop trigger if exists ga4_accounts_touch on public.ga4_accounts; create trigger ga4_accounts_touch before update on public.ga4_accounts for each row execute function private.touch_updated_at(); drop trigger if exists meta_pixels_touch on public.meta_pixels; create trigger meta_pixels_touch before update on public.meta_pixels for each row execute function private.touch_updated_at();
drop trigger if exists meta_ad_accounts_touch on public.meta_ad_accounts; create trigger meta_ad_accounts_touch before update on public.meta_ad_accounts for each row execute function private.touch_updated_at(); alter table public.settings enable row level security; alter table public.ga4_accounts enable row level security; alter table public.meta_pixels enable row level security; alter table public.meta_ad_accounts enable row level security; drop policy if exists "settings: leitura autenticada" on public.settings; create policy "settings: leitura autenticada" on public.settings for select to authenticated using (true); drop policy if exists "ga4_accounts: leitura autenticada" on public.ga4_accounts; create policy "ga4_accounts: leitura autenticada" on public.ga4_accounts for select to authenticated using (true); drop policy if exists "meta_pixels: leitura autenticada" on public.meta_pixels; create policy "meta_pixels: leitura autenticada" on public.meta_pixels for select to authenticated using (true); drop policy if exists "meta_ad_accounts: leitura autenticada" on public.meta_ad_accounts; create policy "meta_ad_accounts: leitura autenticada" on public.meta_ad_accounts for select to authenticated using (true); revoke all on public.settings from anon, authenticated; revoke all on public.ga4_accounts from anon, authenticated; revoke all on public.meta_pixels from anon, authenticated; revoke all on public.meta_ad_accounts from anon, authenticated; grant select ( id, webhook_token_last4, currency, test_event_code, allowed_origins, cookie_domain, insights_cache_ttl_minutes, created_at, updated_at ) on public.settings to authenticated; grant select ( id, label, measurement_id, secret_last4, is_active, created_at, updated_at ) on public.ga4_accounts to authenticated;
grant select ( id, label, pixel_id, secret_last4, is_active, created_at, updated_at ) on public.meta_pixels to authenticated; grant select ( id, label, ad_account_id, secret_last4, is_active, created_at, updated_at ) on public.meta_ad_accounts to authenticated; create or replace function public.set_webhook_token(p_secret text) returns void language plpgsql security definer set search_path = '' as $b011$ declare v_id uuid; begin select webhook_token_secret_id into v_id from public.settings where id; v_id := private.guardar_segredo(v_id, 'rrtrack_webhook_token', p_secret); update public.settings set webhook_token_secret_id = v_id, webhook_token_last4 = private.secret_last4(p_secret) where id; end; $b011$; create or replace function public.set_ga4_secret(p_id uuid, p_secret text) returns void language plpgsql security definer set search_path = '' as $b012$ declare v_id uuid; begin select api_secret_secret_id into v_id from public.ga4_accounts where id = p_id; v_id := private.guardar_segredo(v_id, 'rrtrack_ga4', p_secret); update public.ga4_accounts set api_secret_secret_id = v_id, secret_last4 = private.secret_last4(p_secret) where id = p_id; end; $b012$; create or replace function public.set_meta_pixel_secret(p_id uuid, p_secret text) returns void language plpgsql security definer set search_path = '' as $b013$ declare v_id uuid; begin select capi_token_secret_id into v_id from public.meta_pixels where id = p_id; v_id := private.guardar_segredo(v_id, 'rrtrack_pixel', p_secret); update public.meta_pixels set capi_token_secret_id = v_id, secret_last4 = private.secret_last4(p_secret) where id = p_id; end; $b013$;
create or replace function public.set_meta_ad_account_secret(p_id uuid, p_secret text) returns void language plpgsql security definer set search_path = '' as $b014$ declare v_id uuid; begin select ads_token_secret_id into v_id from public.meta_ad_accounts where id = p_id; v_id := private.guardar_segredo(v_id, 'rrtrack_ads', p_secret); update public.meta_ad_accounts set ads_token_secret_id = v_id, secret_last4 = private.secret_last4(p_secret) where id = p_id; end; $b014$; create or replace function public.get_webhook_token() returns text language sql security definer stable set search_path = '' as $b015$ select private.ler_segredo(webhook_token_secret_id) from public.settings where id; $b015$; create or replace function public.get_ga4_secret(p_id uuid) returns text language sql security definer stable set search_path = '' as $b016$ select private.ler_segredo(api_secret_secret_id) from public.ga4_accounts where id = p_id; $b016$; create or replace function public.get_meta_pixel_secret(p_id uuid) returns text language sql security definer stable set search_path = '' as $b017$ select private.ler_segredo(capi_token_secret_id) from public.meta_pixels where id = p_id; $b017$; create or replace function public.get_meta_ad_account_secret(p_id uuid) returns text language sql security definer stable set search_path = '' as $b018$ select private.ler_segredo(ads_token_secret_id) from public.meta_ad_accounts where id = p_id; $b018$;
do $b019$ declare v_fn text; begin foreach v_fn in array array[ 'public.set_webhook_token(text)', 'public.set_ga4_secret(uuid, text)', 'public.set_meta_pixel_secret(uuid, text)', 'public.set_meta_ad_account_secret(uuid, text)', 'public.get_webhook_token()', 'public.get_ga4_secret(uuid)', 'public.get_meta_pixel_secret(uuid)', 'public.get_meta_ad_account_secret(uuid)' ] loop execute format('revoke all on function %s from public, anon, authenticated', v_fn); execute format('grant execute on function %s to service_role', v_fn); end loop; end; $b019$; create or replace function private.limpar_segredo_da_conta() returns trigger language plpgsql security definer set search_path = '' as $b0110$ begin case tg_table_name when 'ga4_accounts' then perform private.esquecer_segredo(old.api_secret_secret_id); when 'meta_pixels' then perform private.esquecer_segredo(old.capi_token_secret_id); when 'meta_ad_accounts' then perform private.esquecer_segredo(old.ads_token_secret_id); else null; end case; return old; end; $b0110$; drop trigger if exists ga4_accounts_limpa_segredo on public.ga4_accounts; create trigger ga4_accounts_limpa_segredo after delete on public.ga4_accounts for each row execute function private.limpar_segredo_da_conta(); drop trigger if exists meta_pixels_limpa_segredo on public.meta_pixels; create trigger meta_pixels_limpa_segredo after delete on public.meta_pixels for each row execute function private.limpar_segredo_da_conta(); drop trigger if exists meta_ad_accounts_limpa_segredo on public.meta_ad_accounts; create trigger meta_ad_accounts_limpa_segredo after delete on public.meta_ad_accounts for each row execute function private.limpar_segredo_da_conta();
create table if not exists public.visitors ( id uuid primary key default gen_random_uuid(), trck_user_id text not null unique, email text, phone text, first_name text, last_name text, email_hash text, phone_hash text, first_name_hash text, last_name_hash text, city_hash text, state_hash text, country_hash text, external_id_hash text, fbp text, fbc text, ga_client_id text, ga_session_id text, utm_source text, utm_medium text, utm_campaign text, utm_term text, utm_content text, referrer text, landing_url text, ip inet, user_agent text, geo_country text, geo_region text, geo_city text, pixel_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create index if not exists visitors_created_at_idx on public.visitors (created_at desc); create index if not exists visitors_email_hash_idx on public.visitors (email_hash) where email_hash is not null; create index if not exists visitors_phone_hash_idx on public.visitors (phone_hash) where phone_hash is not null; create index if not exists visitors_utm_source_idx on public.visitors (utm_source, created_at desc); create index if not exists visitors_geo_country_idx on public.visitors (geo_country); create table if not exists public.events_log ( id uuid primary key default gen_random_uuid(), event_id text not null unique, trck_user_id text, event_name text not null, utm_source text, utm_medium text, utm_campaign text, utm_term text, utm_content text, event_source_url text, payload_meta jsonb, response_meta jsonb, payload_ga4 jsonb, response_ga4 jsonb, purged_at timestamptz, ip inet, geo_country text, geo_region text, geo_city text, created_at timestamptz not null default now() ); create index if not exists events_log_created_at_idx on public.events_log (created_at desc);
create index if not exists events_log_name_time_idx on public.events_log (event_name, created_at desc); create index if not exists events_log_trck_user_idx on public.events_log (trck_user_id, created_at desc); create index if not exists events_log_purga_idx on public.events_log (created_at) where purged_at is null;
create table if not exists public.purchases ( id uuid primary key default gen_random_uuid(), transaction_id text not null unique, trck_user_id text, email text, email_hash text, phone text, phone_hash text, first_name text, last_name text, product_id text, product_name text, value numeric(14,2), currency text not null default 'BRL', status text not null, platform text, utm_source text, utm_medium text, utm_campaign text, utm_term text, utm_content text, fbp text, fbc text, ga_client_id text, ga_session_id text, geo_country text, geo_region text, geo_city text, match_method text, match_reason text, meta_event_id text, response_meta jsonb, response_ga4 jsonb, sent_at timestamptz, raw_webhook jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint purchases_match_method_valido check ( match_method is null or match_method in ('trck_user_id', 'email', 'phone', 'nenhum') ), constraint purchases_currency_iso check (currency ~ '^[A-Z]{3}$') );
create index if not exists purchases_created_at_idx on public.purchases (created_at desc); create index if not exists purchases_trck_user_idx on public.purchases (trck_user_id); create index if not exists purchases_status_idx on public.purchases (status, created_at desc); create index if not exists purchases_email_hash_idx on public.purchases (email_hash) where email_hash is not null; create index if not exists purchases_utm_source_idx on public.purchases (utm_source, created_at desc); create index if not exists purchases_nao_enviadas_idx on public.purchases (created_at) where sent_at is null; drop trigger if exists visitors_touch on public.visitors; create trigger visitors_touch before update on public.visitors for each row execute function private.touch_updated_at(); drop trigger if exists purchases_touch on public.purchases; create trigger purchases_touch before update on public.purchases for each row execute function private.touch_updated_at(); alter table public.visitors enable row level security; alter table public.events_log enable row level security; alter table public.purchases enable row level security; drop policy if exists "visitors: leitura autenticada" on public.visitors; create policy "visitors: leitura autenticada" on public.visitors for select to authenticated using (true); drop policy if exists "events_log: leitura autenticada" on public.events_log; create policy "events_log: leitura autenticada" on public.events_log for select to authenticated using (true); drop policy if exists "purchases: leitura autenticada" on public.purchases; create policy "purchases: leitura autenticada" on public.purchases for select to authenticated using (true);
revoke insert, update, delete, truncate on public.visitors, public.events_log, public.purchases from anon, authenticated; revoke all on public.visitors, public.events_log, public.purchases from anon; create table if not exists public.rate_limits ( bucket text not null, window_start timestamptz not null, hits integer not null default 0, primary key (bucket, window_start) ); create index if not exists rate_limits_window_idx on public.rate_limits (window_start); create or replace function public.check_rate_limit( p_bucket text, p_limit integer, p_window_seconds integer ) returns boolean language plpgsql volatile security definer set search_path = '' as $b031$ declare v_window timestamptz; v_hits integer; begin if p_limit <= 0 or p_window_seconds <= 0 then raise exception 'limite e janela precisam ser positivos'; end if; v_window := date_bin( make_interval(secs => p_window_seconds), now(), timestamptz 'epoch' ); insert into public.rate_limits as rl (bucket, window_start, hits) values (p_bucket, v_window, 1) on conflict (bucket, window_start) do update set hits = rl.hits + 1 returning rl.hits into v_hits; return v_hits <= p_limit; end; $b031$; create or replace function public.purge_rate_limits(p_older_than_hours integer default 24) returns integer language plpgsql volatile security definer set search_path = '' as $b032$ declare v_apagadas integer; begin delete from public.rate_limits where window_start < now() - make_interval(hours => p_older_than_hours); get diagnostics v_apagadas = row_count; return v_apagadas; end; $b032$;
create table if not exists public.meta_insights_cache ( ad_account_id text not null, level text not null, date_start date not null, date_stop date not null, data jsonb not null, fetched_at timestamptz not null default now(), primary key (ad_account_id, level, date_start, date_stop), constraint meta_insights_level_valido check (level in ('campaign', 'adset', 'ad')), constraint meta_insights_periodo_valido check (date_start <= date_stop) ); create index if not exists meta_insights_fetched_idx on public.meta_insights_cache (fetched_at); alter table public.rate_limits enable row level security; alter table public.meta_insights_cache enable row level security; drop policy if exists "meta_insights_cache: leitura autenticada" on public.meta_insights_cache; create policy "meta_insights_cache: leitura autenticada" on public.meta_insights_cache for select to authenticated using (true); revoke all on public.rate_limits from anon, authenticated; revoke insert, update, delete, truncate on public.meta_insights_cache from anon, authenticated; revoke all on public.meta_insights_cache from anon; revoke all on function public.check_rate_limit(text, integer, integer) from public, anon, authenticated; revoke all on function public.purge_rate_limits(integer) from public, anon, authenticated; grant execute on function public.check_rate_limit(text, integer, integer) to service_role; grant execute on function public.purge_rate_limits(integer) to service_role; alter table public.settings add column if not exists checkout_domains text[] not null default '{}'; comment on column public.settings.checkout_domains is 'Domínios do checkout. O snippet marca com trck_user_id todo link que aponte para um deles. Ex.: {seguro.pagou.ai, checkout.minhaloja.com}';
grant select (checkout_domains) on public.settings to authenticated; create table if not exists public.webhooks_recebidos ( id uuid primary key default gen_random_uuid(), adaptador text, corpo jsonb, corpo_texto text, headers jsonb, ip inet, transaction_id text, created_at timestamptz not null default now() ); create index if not exists webhooks_recebidos_created_idx on public.webhooks_recebidos (created_at desc); create index if not exists webhooks_recebidos_desconhecidos_idx on public.webhooks_recebidos (created_at desc) where adaptador is null; alter table public.webhooks_recebidos enable row level security; drop policy if exists "webhooks_recebidos: leitura autenticada" on public.webhooks_recebidos; create policy "webhooks_recebidos: leitura autenticada" on public.webhooks_recebidos for select to authenticated using (true); revoke insert, update, delete, truncate on public.webhooks_recebidos from anon, authenticated; revoke all on public.webhooks_recebidos from anon; alter table public.purchases add column if not exists reverted_at timestamptz; comment on column public.purchases.reverted_at is 'Quando o estorno foi comunicado aos destinos. NULL = ainda não. Par do sent_at.'; create index if not exists purchases_a_desfazer_idx on public.purchases (created_at) where sent_at is not null and reverted_at is null; alter table public.settings add column if not exists status_aliases text[] not null default '{}'; comment on column public.settings.status_aliases is 'Mapa alias -> status, um por linha, no formato "alias = status". Os aliases de status da Yampi são configuráveis por loja (GET /{alias}/checkout/statuses), então não podem morar no código. Ex.: {"devolvido = estornada", "em_separacao = pendente"}'; grant select (status_aliases) on public.settings to authenticated;
alter table public.webhooks_recebidos add column if not exists motivo text; comment on column public.webhooks_recebidos.motivo is 'Por que o payload não virou venda. NULL quando virou, ou quando nenhum adaptador reconheceu. Distingue "ignorado de propósito" de "não soube ler" — o segundo é venda possivelmente perdida e precisa aparecer no painel.'; alter table public.purchases add column if not exists reverted_value numeric(14,2); comment on column public.purchases.reverted_value is 'Valor que o evento de reversão trouxe. NULL = o gateway não informou, e aí o refund usa o value da venda. Separado de `value` porque estorno parcial existe e nenhum gateway documenta a unidade: sem a separação, um lado dos dois sempre erra.'; grant select (reverted_value) on public.purchases to authenticated; alter table public.settings add column if not exists timezone text not null default 'America/Sao_Paulo'; comment on column public.settings.timezone is 'Fuso em que o painel agrupa os dias. UTC racharia o dia de vendas em duas linhas e o total não bateria com o painel do gateway.'; grant select (timezone) on public.settings to authenticated;
create or replace function public.painel_resumo(de timestamptz, ate timestamptz) returns table ( visitantes bigint, identificados bigint, eventos bigint, aprovadas bigint, receita numeric, pendentes bigint, recusadas bigint, estornadas bigint, devolvido numeric, atribuidas bigint, sem_atribuicao bigint ) language sql stable set search_path = '' as $$ select (select count(*) from public.visitors v where v.created_at >= de and v.created_at < ate), (select count(*) from public.visitors v where v.created_at >= de and v.created_at < ate and v.email_hash is not null), (select count(*) from public.events_log e where e.created_at >= de and e.created_at < ate), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada'), (select coalesce(sum(p.value), 0) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada'), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'pendente'), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'recusada'), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status in ('estornada', 'chargeback')), (select coalesce(sum(coalesce(p.reverted_value, p.value)), 0) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status in ('estornada', 'chargeback')), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada' and p.trck_user_id is not null), (select count(*) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada' and p.trck_user_id is null); $$;
comment on function public.painel_resumo(timestamptz, timestamptz) is 'Os totais do período. `ate` é exclusivo. Receita só de status aprovada — pendente é boleto que ninguém pagou, estornada é dinheiro que voltou.'; create or replace function public.painel_eventos_por_tipo(de timestamptz, ate timestamptz) returns table ( event_name text, total bigint, visitantes bigint ) language sql stable set search_path = '' as $$ select e.event_name, count(*), count(distinct e.trck_user_id) from public.events_log e where e.created_at >= de and e.created_at < ate group by e.event_name order by 2 desc; $$;
create or replace function public.painel_serie_diaria( de timestamptz, ate timestamptz, fuso text default 'America/Sao_Paulo' ) returns table ( dia date, visitantes bigint, eventos bigint, aprovadas bigint, receita numeric ) language sql stable set search_path = '' as $$ with dias as ( select d::date as dia from generate_series( (de at time zone fuso)::date, (ate at time zone fuso)::date - 1, interval '1 day' ) as d ) select dias.dia, coalesce(v.total, 0), coalesce(e.total, 0), coalesce(c.pedidos, 0), coalesce(c.receita, 0) from dias left join ( select (created_at at time zone fuso)::date as dia, count(*) as total from public.visitors where created_at >= de and created_at < ate group by 1 ) v on v.dia = dias.dia left join ( select (created_at at time zone fuso)::date as dia, count(*) as total from public.events_log where created_at >= de and created_at < ate group by 1 ) e on e.dia = dias.dia left join ( select (created_at at time zone fuso)::date as dia, count(*) as pedidos, coalesce(sum(value), 0) as receita from public.purchases where created_at >= de and created_at < ate and status = 'aprovada' group by 1 ) c on c.dia = dias.dia order by dias.dia; $$;
comment on function public.painel_serie_diaria(timestamptz, timestamptz, text) is 'Série por dia no fuso pedido, com os dias vazios inclusos — sem eles o gráfico pularia o dia sem venda e a curva mentiria.';
create or replace function public.painel_geo(de timestamptz, ate timestamptz) returns table ( pais text, regiao text, visitantes bigint, aprovadas bigint, receita numeric ) language sql stable set search_path = '' as $$ with v as ( select geo_country as pais, geo_region as regiao, count(*) as total from public.visitors where created_at >= de and created_at < ate and geo_country is not null group by 1, 2 ), c as ( select geo_country as pais, geo_region as regiao, count(*) as pedidos, coalesce(sum(value), 0) as receita from public.purchases where created_at >= de and created_at < ate and geo_country is not null and status = 'aprovada' group by 1, 2 ) select coalesce(v.pais, c.pais), coalesce(v.regiao, c.regiao), coalesce(v.total, 0), coalesce(c.pedidos, 0), coalesce(c.receita, 0) from v full outer join c on c.pais = v.pais and c.regiao is not distinct from v.regiao order by 5 desc, 3 desc; $$;
revoke all on function public.painel_resumo(timestamptz, timestamptz) from public, anon; revoke all on function public.painel_eventos_por_tipo(timestamptz, timestamptz) from public, anon; revoke all on function public.painel_serie_diaria(timestamptz, timestamptz, text) from public, anon; revoke all on function public.painel_geo(timestamptz, timestamptz) from public, anon; grant execute on function public.painel_resumo(timestamptz, timestamptz) to authenticated; grant execute on function public.painel_eventos_por_tipo(timestamptz, timestamptz) to authenticated; grant execute on function public.painel_serie_diaria(timestamptz, timestamptz, text) to authenticated; grant execute on function public.painel_geo(timestamptz, timestamptz) to authenticated; create or replace function public.painel_receita_por_utm( de timestamptz, ate timestamptz ) returns table ( utm_campaign text, utm_source text, vendas bigint, receita numeric ) language sql stable set search_path = '' as $$ select coalesce(p.utm_campaign, ''), coalesce(p.utm_source, ''), count(*), coalesce(sum(p.value), 0) from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada' group by 1, 2 order by 4 desc; $$; comment on function public.painel_receita_por_utm(timestamptz, timestamptz) is 'Receita aprovada por utm_campaign e utm_source. A campanha vazia agrupa a venda sem atribuição — que é receita real fora de campanha nenhuma.'; revoke all on function public.painel_receita_por_utm(timestamptz, timestamptz) from public, anon; grant execute on function public.painel_receita_por_utm(timestamptz, timestamptz) to authenticated;
/* * O `pg_cron` existe no Supabase e NÃO num Postgres comum. O bloco tolera a * ausência para a migration rodar inteira no teste local — a função de * limpeza, que é onde mora a lógica, é criada dos dois lados. O agendamento * se verifica no Supabase, em `cron.job` e `cron.job_run_details`. */ do $$ begin create extension if not exists pg_cron with schema extensions; exception when others then raise notice 'pg_cron indisponível (esperado fora do Supabase): %', sqlerrm; end; $$;
create or replace function private.aplicar_retencao(p_lote integer default 5000) returns table (tabela text, linhas bigint) language plpgsql security definer set search_path = '' as $$ declare v_n bigint; begin /* * EM LOTES, e `purged_at` é o que torna isso possível. * * Um UPDATE sobre seis meses de eventos trava a tabela por minutos e a * captura para de gravar — o site inteiro perde tracking enquanto a * limpeza roda. Com lote e marca, cada passagem é curta e a seguinte * continua de onde parou. */ with alvo as ( select id from public.events_log where created_at < now() - interval '14 days' and purged_at is null order by created_at limit p_lote for update skip locked ) update public.events_log e set payload_meta = null, response_meta = null, payload_ga4 = null, response_ga4 = null, purged_at = now() from alvo where e.id = alvo.id; get diagnostics v_n = row_count; tabela := 'events_log'; linhas := v_n; return next; with alvo as ( select id from public.webhooks_recebidos where created_at < now() - interval '30 days' and (corpo is not null or corpo_texto is not null or headers is not null) order by created_at limit p_lote for update skip locked ) update public.webhooks_recebidos w set corpo = null, corpo_texto = null, headers = null from alvo where w.id = alvo.id; get diagnostics v_n = row_count; tabela := 'webhooks_recebidos'; linhas := v_n; return next; with alvo as ( select id from public.purchases where created_at < now() - interval '90 days' and raw_webhook is not null order by created_at limit p_lote for update skip locked ) update public.purchases p set raw_webhook = null from alvo where p.id = alvo.id; get diagnostics v_n = row_count; tabela := 'purchases'; linhas := v_n; return next; end; $$;
comment on function private.aplicar_retencao(integer) is 'Zera os campos pesados fora do prazo, em lotes. NUNCA apaga linha: data, evento, UTMs e geo seguem alimentando o painel.'; revoke all on function private.aplicar_retencao(integer) from public, anon, authenticated; do $$ begin perform cron.unschedule('rrtrack-retencao'); exception when others then null; end; $$; do $$ begin perform cron.schedule( 'rrtrack-retencao', '10 4 * * *', 'select private.aplicar_retencao();' ); exception when undefined_function or invalid_schema_name then perform extensions.cron_schedule( 'rrtrack-retencao', '10 4 * * *', 'select private.aplicar_retencao();' ); end; $$;
create or replace function public.painel_paginas( de timestamptz, ate timestamptz ) returns table ( url text, visitantes bigint, checkouts bigint, compras bigint, receita numeric ) language sql stable set search_path = '' as $$ with vistas as ( select distinct split_part(e.event_source_url, '?', 1) as url, e.trck_user_id from public.events_log e where e.created_at >= de and e.created_at < ate and e.event_source_url is not null and e.trck_user_id is not null ), checkouts as ( select distinct split_part(e.event_source_url, '?', 1) as url, e.trck_user_id from public.events_log e where e.created_at >= de and e.created_at < ate and e.event_source_url is not null and e.trck_user_id is not null and lower(e.event_name) in ('initiatecheckout', 'begin_checkout', 'checkout', 'iniciarcheckout') ), compras as ( select p.trck_user_id, count(*) as n, coalesce(sum(p.value), 0) as total from public.purchases p where p.created_at >= de and p.created_at < ate and p.status = 'aprovada' and p.trck_user_id is not null group by 1 ) select v.url, count(distinct v.trck_user_id), count(distinct c.trck_user_id), coalesce(sum(co.n), 0), coalesce(sum(co.total), 0) from vistas v left join checkouts c on c.url = v.url and c.trck_user_id = v.trck_user_id left join compras co on co.trck_user_id = v.trck_user_id group by v.url order by 2 desc; $$;
comment on function public.painel_paginas(timestamptz, timestamptz) is 'Visitantes únicos, checkouts, compras e receita por URL (sem query string). A atribuição é "o visitante viu esta página", então a soma das colunas não fecha com o total do painel.'; revoke all on function public.painel_paginas(timestamptz, timestamptz) from public, anon; grant execute on function public.painel_paginas(timestamptz, timestamptz) to authenticated;
do $inst9$ declare v_tabelas integer; v_sem_rls text[]; v_policy_escrita integer; v_id uuid; v_lido text; v_ponteiro uuid; v_ok boolean := true; begin raise notice ''; raise notice '═══════════════════════════════════════════════════════'; raise notice ' RRTrack · relatório de instalação'; raise notice '═══════════════════════════════════════════════════════'; select array_agg(t) into v_sem_rls from unnest(array[ 'settings', 'ga4_accounts', 'meta_pixels', 'meta_ad_accounts', 'visitors', 'events_log', 'purchases', 'rate_limits', 'meta_insights_cache', 'webhooks_recebidos' ]) as t where not exists ( select 1 from pg_tables where schemaname = 'public' and tablename = t ); select count(*) into v_tabelas from pg_tables where schemaname = 'public'; if v_sem_rls is null then raise notice ' [ok] % tabelas criadas', v_tabelas; else raise notice ' [FALHA] faltaram tabelas: %', v_sem_rls; v_ok := false; end if; v_sem_rls := null; select array_agg(c.relname order by c.relname) into v_sem_rls from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity; if v_sem_rls is null then raise notice ' [ok] RLS ligada em todas as tabelas'; else raise notice ' [FALHA] sem RLS: %', v_sem_rls; v_ok := false; end if; select count(*) into v_policy_escrita from pg_policies where schemaname = 'public' and cmd <> 'SELECT'; if v_policy_escrita = 0 then raise notice ' [ok] Nenhuma policy de escrita (só service_role grava)'; else raise notice ' [FALHA] % policy(s) de escrita encontradas', v_policy_escrita; v_ok := false; end if; if has_column_privilege('authenticated', 'public.meta_pixels', 'capi_token_secret_id', 'SELECT') or has_column_privilege('anon', 'public.settings', 'webhook_token_secret_id', 'SELECT') then raise notice ' [FALHA] ponteiro de segredo legível pelo painel'; v_ok := false; else raise notice ' [ok] Segredos fora do alcance do painel'; end if; insert into public.meta_pixels (label, pixel_id) values ('__verificacao__', '999999999') returning id into v_id; perform public.set_meta_pixel_secret(v_id, 'token-de-verificacao-1234'); select public.get_meta_pixel_secret(v_id) into v_lido; select capi_token_secret_id into v_ponteiro from public.meta_pixels where id = v_id; if v_lido = 'token-de-verificacao-1234' and v_ponteiro is not null then raise notice ' [ok] Cofre guarda e devolve o segredo'; else raise notice ' [FALHA] o cofre não fechou o ciclo'; v_ok := false; end if; delete from public.meta_pixels where id = v_id; if exists (select 1 from vault.secrets where id = v_ponteiro) then raise notice ' [FALHA] o segredo ficou no cofre depois de apagar a conta'; v_ok := false; else raise notice ' [ok] Apagar a conta remove o segredo do cofre'; end if; if public.check_rate_limit('__verificacao__', 1, 60) and not public.check_rate_limit('__verificacao__', 1, 60) then raise notice ' [ok] Rate limit corta no limite'; else raise notice ' [FALHA] rate limit não está cortando'; v_ok := false; end if; delete from public.rate_limits where bucket = '__verificacao__'; raise notice '═══════════════════════════════════════════════════════'; if v_ok then raise notice ' TUDO CERTO. Pode seguir para o passo seguinte.'; else raise notice ' ALGO FALHOU — me mande este relatório.'; end if; raise notice '═══════════════════════════════════════════════════════'; raise notice ''; end; $inst9$;
